          "치료 전에는 임시조정(왁스업, 목업)으로 예상 결과를 확인하고, 디지털인상이나 구강스캐너로 정밀한 수복물을 설계합니다. 영구적 치아삭제나 교합 변경은 신중히 고려해야 합니다."
